using System.IO;
using Autodesk.Revit.DB;

var doc = Document;
var dir = Path.Combine(Path.GetTempPath(), "mcp-ifc-" + System.Guid.NewGuid().ToString("N").Substring(0, 8));
Directory.CreateDirectory(dir);
var name = "model";
var opts = new IFCExportOptions();

// IFC export writes temporary data into the document, so it needs an open transaction
// (unlike DWG export, which manages its own and must be called with none open).
bool ok = false;
Connector.WithTransaction(doc, () => {
    ok = doc.Export(dir, name, opts);
});

var file = Path.Combine(dir, name + ".ifc");
return new { ok, path = file, exists = File.Exists(file), sizeBytes = File.Exists(file) ? new FileInfo(file).Length : 0L };
